const CACHE_NAME="fisika-dev-v1",PRECACHE=["/","/index.html","/style.css","/lab-upgrade.css","/app.js","/addons.js","/manifest.json"];self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE_NAME).then(e=>e.addAll(PRECACHE).catch(()=>{}))),self.skipWaiting()}),self.addEventListener("fetch",e=>{"GET"===e.request.method&&e.respondWith(caches.match(e.request).then(t=>{const s=fetch(e.request).then(t=>(t.ok&&"basic"===t.type&&caches.open(CACHE_NAME).then(s=>s.put(e.request,t.clone())),t)).catch(()=>t);return t||s}))}),self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(e=>Promise.all(e.filter(e=>e!==CACHE_NAME).map(e=>caches.delete(e))))),self.clients.claim()});